COURTS: tuple[GermanCourt, ...] = tuple(GermanCourt(*r) for r in _ROWS)


def _fold(value: str) -> str:
    """Casefold + strip diacritics + drop punctuation — the key both sides of a
    court-name comparison are reduced to, so "Groß-Gerau" and "Gross-Gerau",
    "München" and "Muenchen" are one court."""
    v = unicodedata.normalize("NFKD", value or "")
    v = "".join(c for c in v if not unicodedata.combining(c))
    v = v.replace("ß", "ss").replace("ẞ", "ss")
    # ...and the ASCII transliteration German itself uses where an umlaut can't be typed:
    # "Amtsgericht Huenfeld" and "Amtsgericht Hünfeld" are one court, and the register
    # and the bulk dump disagree about which spelling to publish.
    v = re.sub(r"(?<=[aou])e(?=[a-z])", "", v.casefold())
    return re.sub(r"[^a-z0-9]+", "", v)


#: Spellings the generated table cannot produce, by slug. The seat of a court whose
#: name does not contain it, and which the register's alias list omits — a German
#: judgment writes "KG Berlin" and "BGH Karlsruhe" as readily as the bare abbreviation.
_EXTRA_SPELLINGS: dict[str, tuple[str, ...]] = {
    "kg-": ("KG Berlin", "Kammergericht Berlin"),
    "bgh": ("BGH Karlsruhe",),
    "bverfg": ("BVerfG Karlsruhe",),
    "bverwg": ("BVerwG Leipzig",),
    "bag": ("BAG Erfurt",),
    "bsg": ("BSG Kassel",),
    "bfh": ("BFH München",),
    "bpatg": ("BPatG München",),
}


def _spellings(court: GermanCourt) -> set[str]:
    """Every way this court may be written: its full name, and — where it has a
    type — that type's abbreviation and word combined with each seat/state spelling,
    in both German orders ("VG Köln" and "Köln VG")."""
    out = {court.name, *_EXTRA_SPELLINGS.get(court.slug, ())}
    words = [w for w in (TYPE_WORDS.get(court.court_type), court.court_type) if w]
    # The seat inside the court's OWN name, read here rather than baked into ``places``:
    # where the register and the dump disagreed about a name, the better-spelled one won
    # and the generated seat list still carries the OCR'd form ("Biidingen" beside
    # "Amtsgericht Büdingen"), so "AG Büdingen" would have resolved to nothing.
    places = set(court.places)
    for w in words:
        if court.name.startswith(f"{w} "):
            places.add(court.name[len(w) + 1:])
    for place in places:
        for w in words:
            out.add(f"{w} {place}")
            out.add(f"{place} {w}")
    return out


@lru_cache(maxsize=1)
def _index() -> tuple[dict[str, GermanCourt], dict[str, GermanCourt], dict[str, GermanCourt]]:
    """(by folded spelling, by ECLI code, by slug).

    The spelling index applies the ambiguity gate: a spelling claimed by more than one
    court names none of them (see the module docstring — "VG Nordrhein-Westfalen" is ten
    different courts). A court's own ``name`` is exempt from the gate only in the sense
    that it is registered first; if two courts genuinely share a name, neither wins.
    """
    claims: dict[str, set[str]] = {}
    for c in COURTS:
        for spelling in _spellings(c):
            claims.setdefault(_fold(spelling), set()).add(c.slug)
    by_slug = {c.slug: c for c in COURTS}
    by_spelling = {k: by_slug[next(iter(v))] for k, v in claims.items() if len(v) == 1}
    # The ECLI token → the PRIMARY court of that seat. A specialist tribunal shares its
    # host court's token (Anwaltsgerichtshof NRW → OLGHAM), so prefer the court that
    # carries an ordinary court_type, then the shorter name — the host, not its lodger.
    by_code: dict[str, GermanCourt] = {}
    for c in sorted(COURTS, key=lambda c: (not c.court_type, len(c.name))):
        by_code.setdefault(_fold(c.code), c)
    return by_spelling, by_code, by_slug


def by_code(code: str | None) -> GermanCourt | None:
    """The court an ECLI court token names — ``"OVGNRW"`` → Oberverwaltungsgericht NRW."""
    return _index()[1].get(_fold(code or "")) if code else None


def by_slug(slug: str | None) -> GermanCourt | None:
    """The court an openlegaldata slug names (the adapter's own key)."""
    return _index()[2].get((slug or "").strip().lower())


def find(value: str | None) -> GermanCourt | None:
    """The court this text names, however it is written — a full name, an
    abbreviation + seat, an ECLI court token, or a whole ECLI. None when the text
    names no court, or names one too ambiguously to choose (see ``_index``)."""
    raw = " ".join((value or "").split())
    if not raw:
        return None
    if raw.upper().startswith("ECLI:"):
        parts = raw.split(":")
        return by_code(parts[2]) if len(parts) >= 3 else None
    return _index()[0].get(_fold(raw)) or by_code(raw) or by_slug(raw.lower())


def court_name(value: str | None) -> str | None:
    """The canonical display name for anything that names a German court, or the
    foreign-court name where the corpus knows one; else None."""
    court = find(value)
    if court is not None:
        return court.name
    return FOREIGN_COURT_NAMES.get(_fold(value or "").upper()) or \
        FOREIGN_COURT_NAMES.get((value or "").strip().upper())


def court_key(value: str | None) -> str | None:
    """The canonical key for a court — its ECLI token where the table knows it.

    This is what ``citations.german.case_alias`` keys a docket citation on, so
    "OVG Münster, 13 A 1234/20" and the harvested ``ECLI:DE:OVGNRW:…`` decision meet
    at ``de:case:OVGNRW:13A1234/20``. A tribunal that shares its host's ECLI token
    keys on its own slug instead, so its dockets don't merge into the host's."""
    court = find(value)
    if court is None:
        return None
    primary = by_code(court.code)
    if primary is not None and primary.slug != court.slug:
        return court.slug.upper()
    return court.code.upper()


#: The court-type abbreviations a German citation writes before a seat — "OVG Münster",
#: "VG Köln", "LAG Hamm". Longest-first so "OVG" is never cut short to "VG", and
#: restricted to types the table actually holds.
_TYPES_BY_LENGTH = tuple(sorted(
    {c.court_type for c in COURTS if c.court_type} | {"ARBG", "ARBG"},
    key=len, reverse=True))
#: Court abbreviations that stand alone, with no seat: the federal courts, the
#: Kammergericht, and the two European courts a German judgment cites by name.
STANDALONE_COURTS = ("BVerfG", "BVerwG", "BPatG", "BGH", "BAG", "BFH", "BSG", "BayObLG",
                     "BayVGH", "KG", "GmSOGB", "EuGH", "EuG", "EGMR")
#: ``OVG Münster`` / ``VG Köln`` / ``ArbG Berlin`` — a type abbreviation followed by a
#: capitalised seat (which may be hyphenated or two words: "Berlin-Brandenburg",
#: "Frankfurt am Main"). Kept to ONE optional continuation so it cannot run into prose.
_SEAT = r"[A-ZÄÖÜ][\wÄÖÜäöüß]*(?:[-\s](?:am|an|der|des|a\.|d\.)?\s*[A-ZÄÖÜ][\wÄÖÜäöüß]*)?"
COURT_RE_SOURCE = (
    r"(?:(?:" + "|".join(re.escape(t) for t in STANDALONE_COURTS) + r")"
    r"|(?:" + "|".join(sorted({t.title() if t.isupper() and len(t) > 3 else t
                               for t in _TYPES_BY_LENGTH} | set(_TYPES_BY_LENGTH),
                              key=len, reverse=True)) + r")\s+" + _SEAT + r")"
)
